<?php
declare(strict_types=1);
require_once __DIR__.'/NativePortalConsentCapability.php';
require_once __DIR__.'/NativeCompanyConsentSchema.php';
require_once __DIR__.'/NativeCompanyResourceId.php';
/** Contact consent history in the canonical store, with explicit purpose provenance. */
final class NativePortalConsentLedger
{
 public function __construct(private$db,private string$p,private NativePortalConsentCapability$cap){$cap->assertStorageBinding($db,$p);}
 private function rows(string$sql,array$args=[]):array{return IssuerStorage::query($this->db,$sql,$args)->result_array();}
 private function who(int$issuer,string$token):array{$this->cap->assertStorageBinding($this->db,$this->p);return$this->cap->resolve($issuer,$token);}
 public function tables():array{return['issuers_lock','issuers_registry','issuers_installation_identity','issuers_clients','issuers_audit','contacts','clients','options','company_native_consent_purposes','company_native_consents','consent_purposes','consents'];}
 private function primary(int$issuer):bool{return(int)($this->rows('SELECT primary_issuer_id FROM '.$this->p.'issuers_installation_identity WHERE id=1')[0]['primary_issuer_id']??0)===$issuer;}
 public function page(int$issuer,string$token):array{
  $who=$this->who($issuer,$token);NativeCompanyConsentSchema::assertValid($this->db,$this->p);$contact=$who['contact_id'];$purposes=[];$history=[];
  foreach($this->rows('SELECT * FROM '.$this->p.'company_native_consent_purposes WHERE issuer_id=? ORDER BY name,id',[$issuer])as$row){$row['source_kind']='company_consent_purpose';$row['source_id']=(int)$row['id'];$row['id']=NativeCompanyResourceId::encode($row['source_kind'],$row['source_id']);$row['revision']=(string)$row['revision'];$purposes[$row['id']]=$row;}
  if($this->primary($issuer))foreach($this->rows('SELECT * FROM '.$this->p.'consent_purposes ORDER BY name,id')as$row){$row['source_kind']='consent_purpose';$row['source_id']=(int)$row['id'];$row['revision']=hash('sha256',json_encode($row,JSON_THROW_ON_ERROR));$row['id']=NativeCompanyResourceId::encode('consent_purpose',$row['source_id']);$purposes[$row['id']]=$row;}
  foreach($this->rows('SELECT * FROM '.$this->p.'company_native_consents WHERE issuer_id=? AND contact_id=? ORDER BY id DESC',[$issuer,$contact])as$row){if(!in_array($row['purpose_source'],['company_consent_purpose','consent_purpose'],true)||($row['purpose_source']==='consent_purpose'&&!$this->primary($issuer)))throw new RuntimeException('native_consent_history_invalid');$record=json_decode($row['record_json'],true,32,JSON_THROW_ON_ERROR);if(!is_array($record))throw new RuntimeException('native_consent_history_invalid');$history[]=$record+['id'=>NativeCompanyResourceId::encode('company_consent',(int)$row['id']),'purpose_id'=>NativeCompanyResourceId::encode($row['purpose_source'],(int)$row['purpose_id']),'contact_id'=>$contact,'date'=>$row['created_at']];}
  if($this->primary($issuer))foreach($this->rows('SELECT c.*,p.name AS purpose_name FROM '.$this->p.'consents c LEFT JOIN '.$this->p.'consent_purposes p ON p.id=c.purpose_id WHERE c.contact_id=? AND c.lead_id=0 ORDER BY c.id DESC',[$contact])as$row){$row['id']=NativeCompanyResourceId::encode('consent',(int)$row['id']);$row['purpose_id']=NativeCompanyResourceId::encode('consent_purpose',(int)$row['purpose_id']);$history[]=$row;}
  usort($history,static fn($a,$b)=>strcmp($b['date'],$a['date'])?:strcmp((string)$b['id'],(string)$a['id']));foreach($purposes as&$purpose){$last=null;foreach($history as$record)if((string)$record['purpose_id']===(string)$purpose['id']){$last=$record;break;}$purpose['consent_given']=($last['action']??null)==='opt-in'?1:0;$purpose['last_action_is_opt_out']=($last['action']??null)==='opt-out'?1:0;$purpose['consent_last_updated']=$last['date']??null;$purpose['opt_in_purpose_description']=$last['opt_in_purpose_description']??'';}unset($purpose);
  $this->who($issuer,$token);return['contact'=>$who,'purposes'=>array_values($purposes),'history'=>$history,'revision'=>hash('sha256',json_encode([$issuer,$contact,$purposes,$history],JSON_THROW_ON_ERROR))];
 }
 public function record(int$issuer,string$token,string$revision,string$key,array$actions,string$ip):array{
  if(!preg_match('/^[a-f0-9]{64}$/D',$revision)||!preg_match('/^[a-f0-9]{64}$/D',$key)||!filter_var($ip,FILTER_VALIDATE_IP)||count($actions)>1000)throw new DomainException('native_consent_invalid');foreach($actions as$id=>$action)if(!in_array($action,['opt-in','opt-out'],true)||!is_scalar($id))throw new DomainException('native_consent_invalid');ksort($actions,SORT_STRING);
  return IssuerTransaction::run($this->db,$this->p,$this->tables(),function()use($issuer,$token,$revision,$key,$actions,$ip){$who=$this->who($issuer,$token);$contact=$who['contact_id'];$hash=hash('sha256',json_encode([$revision,$actions],JSON_THROW_ON_ERROR));$nonce=static fn($position)=>hash('sha256',json_encode(['native-contact-consent-batch',$issuer,$contact,$key,$position],JSON_THROW_ON_ERROR));
   $first=$this->rows('SELECT * FROM '.$this->p.'company_native_consents WHERE nonce=?',[$nonce(0)])[0]??null;if($first){$saved=json_decode($first['record_json'],true,32,JSON_THROW_ON_ERROR);if((int)$first['issuer_id']!==$issuer||(int)$first['contact_id']!==$contact||($saved['batch_hash']??null)!==$hash||($saved['batch_count']??null)!==count($actions))throw new DomainException('native_consent_replay_conflict');$ids=[];foreach(array_keys($actions)as$position=>$wire){$row=$this->rows('SELECT * FROM '.$this->p.'company_native_consents WHERE nonce=?',[$nonce($position)])[0]??null;$record=$row?json_decode($row['record_json'],true,32,JSON_THROW_ON_ERROR):[];$ref=NativeCompanyResourceId::decode('consent_purpose',$wire);if(!$row||($record['batch_hash']??null)!==$hash||($record['action']??null)!==$actions[$wire]||(int)$row['contact_id']!==$contact||(int)$row['issuer_id']!==$issuer||$row['purpose_source']!==$ref['source_kind']||(int)$row['purpose_id']!==$ref['source_id'])throw new RuntimeException('issuer_consent_batch_unconfirmed');$ids[]=NativeCompanyResourceId::encode('company_consent',(int)$row['id']);}$this->who($issuer,$token);return$ids;}
   $state=$this->page($issuer,$token);if(!hash_equals($state['revision'],$revision))throw new DomainException('company_client_stale');$catalog=[];foreach($state['purposes']as$purpose)$catalog[(string)$purpose['id']]=$purpose;$ids=[];$position=0;
   foreach($actions as$wire=>$action){$purpose=$catalog[(string)$wire]??null;if(!$purpose)throw new DomainException('native_consent_invalid');$record=['action'=>$action,'purpose_name'=>$purpose['name'],'purpose_revision'=>$purpose['revision'],'description'=>'Consent Updated From Web Form','opt_in_purpose_description'=>$purpose['description']??'','staff_name'=>null,'actor_kind'=>'contact','contact_id'=>$contact,'ip'=>$ip,'batch_hash'=>$hash,'batch_count'=>count($actions),'batch_position'=>$position];$json=json_encode($record,JSON_THROW_ON_ERROR);$at=gmdate('Y-m-d H:i:s');$receipt=$nonce($position++);IssuerStorage::query($this->db,'INSERT INTO '.$this->p.'company_native_consents(issuer_id,contact_id,purpose_id,record_json,nonce,created_at,purpose_source) VALUES(?,?,?,?,?,?,?)',[$issuer,$contact,$purpose['source_id'],$json,$receipt,$at,$purpose['source_kind']]);$raw=(int)$this->db->insert_id();$actual=$this->rows('SELECT * FROM '.$this->p.'company_native_consents WHERE id=? AND nonce=?',[$raw,$receipt])[0]??null;if(!$actual||$actual['record_json']!==$json||(int)$actual['issuer_id']!==$issuer||(int)$actual['contact_id']!==$contact||$actual['purpose_source']!==$purpose['source_kind']||(int)$actual['purpose_id']!==$purpose['source_id'])throw new RuntimeException('issuer_consent_batch_unconfirmed');$ids[]=NativeCompanyResourceId::encode('company_consent',$raw);}
   if($ids){$meta=json_encode(['actor_kind'=>'contact','contact_id'=>$contact,'batch_hash'=>$hash,'receipts'=>$ids,'nonce'=>bin2hex(random_bytes(32))],JSON_THROW_ON_ERROR);IssuerStorage::query($this->db,'INSERT INTO '.$this->p.'issuers_audit(actor_id,event,issuer_id,subject_id,metadata_json,created_at) VALUES(0,?,?,?,?,?)',['native_portal_consent_recorded',$issuer,$contact,$meta,gmdate('Y-m-d H:i:s')]);if(count($this->rows('SELECT id FROM '.$this->p.'issuers_audit WHERE issuer_id=? AND subject_id=? AND metadata_json=?',[$issuer,$contact,$meta]))!==1)throw new RuntimeException('issuer_consent_batch_unconfirmed');}$this->who($issuer,$token);return$ids;
  });
 }
}
